MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353.

    A Polish sequence is the preorder list of child counts in an ordered rooted
    tree. Equivalently, its running number of unfilled child positions stays
    positive until the final item, where it becomes zero.
    """
    # Factorials support the ballot number for a forest of roots.
    fact = [1] * (2 * n + 1)
    for i in range(1, len(fact)):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[-1] = pow(fact[-1], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top or top < 0:
            return 0
        return fact[top] * invfact[bottom] % MOD * invfact[top - bottom] % MOD

    def forests(nodes: int, roots: int) -> int:
        # Number of ordered forests with roots roots and nodes total nodes.
        if nodes == 0:
            return int(roots == 0)
        if roots < 1 or roots > nodes:
            return 0
        return roots * pow(nodes, MOD - 2, MOD) % MOD * choose(
            2 * nodes - roots - 1, nodes - roots
        ) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1

        # First differing position: choose a smaller child count. After that
        # choice the suffix must encode a forest with the resulting open slots.
        if remaining:
            low = max(1, slots - 1)
            high = min(remaining, slots + bound - 2)
            for roots in range(low, high + 1):
                answer += forests(remaining, roots)
        else:
            # At the last position only the exact value that closes the tree
            # is valid; smaller values cannot fill the remaining slots.
            if slots - 1 < bound and slots - 1 == 0:
                answer += 1

        slots += bound - 1
        if slots < 0:
            break
        if slots == 0:
            # Equality has completed a valid sequence only at n.
            if i == n - 1:
                answer += 1
            break

    return answer % MOD

