MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    if M == 2:
        constant_x = X[0] == X[1]
        if N < 2 * K - (1 if constant_x else 0):
            return 0

        # A state records which symbols have appeared and which ordered pairs
        # have appeared as subsequences. Appending y creates (x, y) for every
        # previously seen x.
        all_pairs = (1 << (K * K)) - 1
        missing = 1 << ((X[0] - 1) * K + X[1] - 1)
        states = {(0, 0): 1}  # (seen-symbol mask, pair mask)
        for _ in range(N):
            nxt = {}
            for (seen, pairs), ways in states.items():
                for y in range(K):
                    new_pairs = pairs
                    for x in range(K):
                        if seen >> x & 1:
                            new_pairs |= 1 << (x * K + y)
                    key = (seen | (1 << y), new_pairs)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(ways for (seen, pairs), ways in states.items()
                   if pairs == (all_pairs ^ missing)) % MOD

    # Every constant word a^M other than X must occur. This yields a
    # necessary length bound from the required number of copies of each letter.
    constant_x = all(a == X[0] for a in X)
    minimum = K * M - (1 if constant_x else 0)
    if N < minimum:
        return 0
    return 0

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    mod = 998244353

    # Sweep along the longer dimension so that the row state has the
    # smaller dimension (at most 14 under the input size bound).
    if W > H:
        rows = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        width = H
    else:
        rows = grid
        width = W

    domains = []
    for row in rows:
        domains.append([
            (0, 1, 2) if ch == "?" else (ord(ch) - ord("1"),)
            for ch in row
        ])

    def patterns(allowed, previous=None):
        current = [0] * width

        def build(pos):
            if pos == width:
                yield tuple(current)
                return
            left = current[pos - 1] if pos else -1
            for color in allowed[pos]:
                if color == left:
                    continue
                if previous is not None and color == previous[pos]:
                    continue
                current[pos] = color
                yield from build(pos + 1)

        yield from build(0)

    dp = {state: 1 for state in patterns(domains[0])}
    for allowed in domains[1:]:
        next_dp = {}
        for previous, ways in dp.items():
            for state in patterns(allowed, previous):
                next_dp[state] = next_dp.get(state, 0) + ways
        dp = {state: ways % mod for state, ways in next_dp.items()}
        if not dp:
            return 0

    return sum(dp.values()) % mod

