from math import gcd


def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating symmetry-preserving moves can color the circle."""
    if n % 4 == 0 or gcd(n, k) > 2:
        return False

    # A threefold rotational stabilizer prevents completion when the axes are
    # separated by one step modulo 3, except when Bob's axis is adjacent to Alice's.
    if n % 3 == 0 and k % 3 == 2 and k != n - 1:
        return False
    return True

