MOD = 998244353


def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct indegree sequences of orientations of the specified graph."""
    # A cycle edge i -- i+1 is encoded by b_i=1 when it points into i.
    # The cycle contribution at i is 1 + b_i - b_(i-1). An optional spoke
    # adds either zero or one to that contribution.
    #
    # For a proposed sequence of indegrees, its possible edge-bit sequences
    # form a two-state automaton. Determinizing from each possible starting
    # bit lets us count output sequences (rather than orientations), with
    # cyclic closure checked at the end.
    def advance(mask: int, y: int, spoke: bool) -> int:
        nxt = 0
        for prev in (0, 1):
            if not (mask & (1 << prev)):
                continue
            for cur in (0, 1):
                base = 1 + cur - prev
                if y == base or (spoke and y == base + 1):
                    nxt |= 1 << cur
        return nxt

    # Pair of reachable-state masks, one for each fixed initial edge bit.
    dp = {(1, 2): 1}
    for ch in s:
        ndp = {}
        spoke = ch == "1"
        for (from_zero, from_one), ways in dp.items():
            for y in range(4):
                a = advance(from_zero, y, spoke)
                b = advance(from_one, y, spoke)
                if a or b:
                    key = (a, b)
                    ndp[key] = (ndp.get(key, 0) + ways) % MOD
        dp = ndp
    answer = 0
    for (from_zero, from_one), ways in dp.items():
        if (from_zero & 1) or (from_one & 2):
            answer = (answer + ways) % MOD
    return answer

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    mod = 998244353

    # Transfer across the shorter dimension to keep the row state space small.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    fixed_rows = [
        tuple(-1 if ch == "?" else ord(ch) - ord("1") for ch in row)
        for row in grid
    ]

    # A row state is a horizontally proper color sequence, encoded in base 3.
    # Keep only states that agree with that row's fixed cells.
    row_states = []
    for fixed in fixed_rows:
        states = []

        def build_states(col, previous, code):
            if col == W:
                states.append(code)
                return
            allowed = range(3) if fixed[col] < 0 else (fixed[col],)
            for color in allowed:
                if color != previous:
                    build_states(col + 1, color, code * 3 + color)

        build_states(0, -1, 0)
        row_states.append(states)

    # Decode states once; transitions are generated from a source state by
    # choosing each destination color subject to both vertical and horizontal
    # constraints.
    def decode(code):
        colors = [0] * W
        for i in range(W - 1, -1, -1):
            colors[i] = code % 3
            code //= 3
        return colors

    states_by_row = [[(code, decode(code)) for code in states] for states in row_states]
    dp = {code: 1 for code in row_states[0]}

    for r in range(1, H):
        fixed = fixed_rows[r]
        target_index = {code: code for code in row_states[r]}
        next_dp = {}

        for source_code, ways in dp.items():
            source = decode(source_code)
            out = [0] * W

            def extend(col, previous, code):
                if col == W:
                    target = target_index.get(code)
                    if target is not None:
                        next_dp[target] = (next_dp.get(target, 0) + ways) % mod
                    return
                required = fixed[col]
                if required >= 0:
                    if required != source[col] and required != previous:
                        extend(col + 1, required, code * 3 + required)
                    return
                for color in range(3):
                    if color != source[col] and color != previous:
                        extend(col + 1, color, code * 3 + color)

            extend(0, -1, 0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % mod

