_ROOT = 3


def _ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a, b, limit):
    out_len = min(limit, len(a) + len(b) - 1)
    if len(a) * len(b) <= 4096:
        out = [0] * out_len
        for i, x in enumerate(a):
            upto = min(len(b), out_len - i)
            for j in range(upto):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    n = 1
    full_len = len(a) + len(b) - 1
    while n < full_len:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:out_len]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1 through K with each letter count
    bounded by its corresponding entry in C, modulo 998244353.
    """
    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % _MOD
    invfact = [1] * (K + 1)
    invfact[K] = pow(fact[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % _MOD

    polys = []
    for cap in C:
        degree = min(cap, K)
        polys.append(invfact[:degree + 1])

    while len(polys) > 1:
        next_level = []
        for i in range(0, len(polys), 2):
            if i + 1 == len(polys):
                next_level.append(polys[i])
            else:
                next_level.append(_multiply(polys[i], polys[i + 1], K + 1))
        polys = next_level

    coeff = polys[0]
    return sum(coeff[n] * fact[n] for n in range(1, len(coeff))) % _MOD

def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations satisfying the LIS/LDS and extension conditions."""
    # RSK shape: B rows of length A, with the lower-right cell omitted.
    caps = (A,) * (B - 1) + (A - 1,)
    zero = (0,) * B
    full = caps
    states = []

    def build(row, previous, prefix):
        if row == B:
            states.append(tuple(prefix))
            return
        for length in range(min(caps[row], previous) + 1):
            prefix.append(length)
            build(row + 1, length, prefix)
            prefix.pop()

    build(0, A, [])
    states.sort(key=sum)

    # Number of ways to reach each ideal from the empty diagram.
    ways_from = {zero: 1}
    for state in states[1:]:
        total = 0
        for r, length in enumerate(state):
            if length and (r + 1 == B or length > state[r + 1]):
                prev = list(state)
                prev[r] -= 1
                total += ways_from[tuple(prev)]
        ways_from[state] = total % M

    # Walk backward one rank at a time, retaining only the next rank's
    # completion counts. Their product with ways_from counts tableaux
    # whose entries in the ideal precede those outside it.
    qualifying = 0
    end = len(states)
    next_ways = {full: 1}
    while end:
        size = sum(states[end - 1])
        start = end - 1
        while start and sum(states[start - 1]) == size:
            start -= 1
        current_ways = {}
        for state in states[start:end]:
            total = 0
            for r, length in enumerate(state):
                if length < caps[r] and (r == 0 or length < state[r - 1]):
                    nxt = list(state)
                    nxt[r] += 1
                    total += next_ways[tuple(nxt)]
            current_ways[state] = total % M
            if state[B - 1] >= 1 and state[0] <= A - 1:
                qualifying = (qualifying + ways_from[state] * total) % M
        next_ways = current_ways
        end = start

    return (ways_from[full] * qualifying) % M

