    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [i for i in range(2, limit + 1) if sieve[i]]

    vals = []
    left = 1
    while left <= n:
        q = n // left
        vals.append(q)
        left = n // q + 1
    # vals are in decreasing order, so every x//p needed below has an index.
    index = {v: i for i, v in enumerate(vals)}

    counts = []
    for r in range(3):
        # Number of integers in [2,x] congruent to r modulo 3.
        row = []
        for x in vals:
            c = (x - r) // 3 + 1 if x >= r else 0
            if r == 1:
                c -= 1
            row.append(c)
        counts.append(row)

    small_prefix = [[0] * (limit + 1) for _ in range(3)]
    seen = [0, 0, 0]
    prime_pos = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            seen[x % 3] += 1
        for r in range(3):
            small_prefix[r][x] = seen[r]

    for p in primes:
        p2 = p * p
        if p2 > n:
            break
        rp = p % 3
        for k, x in enumerate(vals):
            if x < p2:
                break
            qidx = index[x // p]
            lower = p - 1
            for s in range(3):
                r = (rp * s) % 3
                counts[r][k] -= counts[s][qidx] - small_prefix[s][lower]

