def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences with product at most N
    whose product has a divisor sum divisible by 3, modulo 998244353.
    """
    primes, vals, index, prime_counts = _prime_data(N)
    root = isqrt(N)

    # Prime-count prefixes over the explicitly sieved primes.
    prefix_h = [0] * (len(primes) + 1)
    for i, p in enumerate(primes):
        prefix_h[i + 1] = prefix_h[i] + (1 if p % 3 in (0, 1) else 0)

    all_count = [sum(row[k] for row in prime_counts) for k in range(len(vals))]
    h_count = [prime_counts[0][k] + prime_counts[1][k] for k in range(len(vals))]

    def binom_weight(e):
        # C(M+e-1,e), with e bounded by log_2(N).
        out = 1
        for t in range(1, e + 1):
            out = out * (M + t - 1) % MOD
            out = out * pow(t, MOD - 2, MOD) % MOD
        return out

    weights = [0] * (34)
    for e in range(1, len(weights)):
        weights[e] = binom_weight(e)

    def sum_multiplicative(use_sigma_square):
        @lru_cache(maxsize=None)
        def rec(x, j):
            if x < 2 or j >= len(primes) or primes[j] > x:
                return 1
            p = primes[j]
            if p * p > x:
                k = index[x]
                cnt = (h_count[k] - prefix_h[j]) if use_sigma_square else (all_count[k] - j)
                return (1 + M * cnt) % MOD

            ans = 1
            i = j
            while i < len(primes):
                p = primes[i]
                if p * p > x:
                    k = index[x]
                    cnt = (h_count[k] - prefix_h[i]) if use_sigma_square else (all_count[k] - i)
                    ans += M * cnt
                    break

                power = p
                e = 1
                while power <= x:
                    h = 1
                    if use_sigma_square:
                        if p % 3 == 2:
                            h = 1 if e % 2 == 0 else 0
                        elif p % 3 == 1:
                            h = 0 if e % 3 == 2 else 1
                    if h:
                        ans += weights[e] * h * rec(x // power, i + 1)
                    if power > x // p:
                        break
                    power *= p
                    e += 1
                i += 1
            return ans % MOD

        return rec(N, 0)

    total = sum_multiplicative(False)
    nonzero_sigma = sum_multiplicative(True)
    return (total - nonzero_sigma) % MOD

MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a.

    Polish sequences are preorder child-count encodings of ordered rooted
    trees. The number of unfilled child positions starts at one, stays positive
    before the last item, and becomes zero at the last item.
    """
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top or top < 0:
            return 0
        return fact[top] * invfact[bottom] % MOD * invfact[top - bottom] % MOD

    def forests(nodes: int, roots: int) -> int:
        # Ordered forests with roots roots and nodes total nodes.
        if nodes == 0:
            return int(roots == 0)
        if roots < 1 or roots > nodes:
            return 0
        return roots * fact[nodes - 1] % MOD * invfact[nodes] % MOD * choose(
            2 * nodes - roots - 1, nodes - roots
        ) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1

        # For a smaller value x, the suffix is a forest with slots - 1 + x
        # roots. Sum the ballot counts for all such x.
        if remaining:
            low = max(1, slots - 1)
            high = min(remaining, slots + bound - 2)
            for roots in range(low, high + 1):
                answer += forests(remaining, roots)
        elif slots == 1 and bound > 0:
            # A smaller final value can close the last open position only when
            # it is zero.
            answer += 1

        slots += bound - 1
        if slots < 0:
            break
        if slots == 0:
            if i == n - 1:
                answer += 1
            break

    return answer % MOD

