            start -= 1
        current_ways = {}
        for state in states[start:end]:
            total = 0
            for r, length in enumerate(state):
                if length < caps[r] and (r == 0 or length < state[r - 1]):
                    nxt = list(state)
                    nxt[r] += 1
                    total += next_ways[tuple(nxt)]
