def _prime_data(n):
    limit = isqrt(n)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [i for i in range(2, limit + 1) if sieve[i]]

    vals = []
    left = 1
    while left <= n:
        q = n // left
        vals.append(q)
        left = n // q + 1
    index = {v: i for i, v in enumerate(vals)}

    counts = []
    for r in range(3):
        row = []
        for x in vals:
            c = (x - r) // 3 + 1 if x >= r else 0
            if r == 1:
                c -= 1
            row.append(c)
        counts.append(row)

    prefix = [[0] * (limit + 1) for _ in range(3)]
    seen = [0, 0, 0]
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            seen[x % 3] += 1
        for r in range(3):
            prefix[r][x] = seen[r]

    for p in primes:
        p2 = p * p
        if p2 > n:
            break
        rp = p % 3
        # vals are descending; only visit quotients at least p squared.
        for k, x in enumerate(vals):
            if x < p2:
                break
            qidx = index[x // p]
            before = prefix[0][p - 1], prefix[1][p - 1], prefix[2][p - 1]
            for s in range(3):
                r = (rp * s) % 3
                counts[r][k] -= counts[s][qidx] - before[s]

    return primes, vals, index, counts


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences whose product is at most N
    and has a divisor sum divisible by 3, modulo 998244353.
    """
    primes, vals, index, prime_counts = _prime_data(N)
    prefix_h = [0] * (len(primes) + 1)
    for i, p in enumerate(primes):
        prefix_h[i + 1] = prefix_h[i] + (p % 3 in (0, 1))

    all_count = [sum(row[k] for row in prime_counts) for k in range(len(vals))]
    h_count = [prime_counts[0][k] + prime_counts[1][k] for k in range(len(vals))]
    weights = [0] * 34
    weights[0] = 1
    for e in range(1, 34):
        weights[e] = weights[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def sum_multiplicative(use_sigma_square):
        @lru_cache(maxsize=None)
        def rec(x, j):
            if x < 2:
                return 1

            def prime_tail(start):
                k = index[x]
                if use_sigma_square:
                    return (1 + M * max(0, h_count[k] - prefix_h[start])) % MOD
                return (1 + M * max(0, all_count[k] - start)) % MOD

            if j >= len(primes):
                return prime_tail(j)
            if primes[j] > x or primes[j] * primes[j] > x:
                return prime_tail(j)

            ans = 1
            i = j
            while i < len(primes) and primes[i] * primes[i] <= x:
                p = primes[i]
                power = p
                e = 1
                while power <= x:
                    h = 1
                    if use_sigma_square:
                        if p % 3 == 2:
                            h = int(e % 2 == 0)
                        elif p % 3 == 1:
                            h = int(e % 3 != 2)
                    if h:
                        ans += weights[e] * rec(x // power, i + 1)
                    if power > x // p:
                        break
                    power *= p
                    e += 1
                i += 1

            # All remaining primes are larger than sqrt(x), so each occurs
            # only as a prime by itself in this branch.
            if i < len(primes) or i == len(primes):
                k = index[x]
                cnt = (h_count[k] - prefix_h[i]) if use_sigma_square else (all_count[k] - i)
                ans += M * max(0, cnt)
            return ans % MOD

        return rec(N, 0)

    return (sum_multiplicative(False) - sum_multiplicative(True)) % MOD

from typing import List

_MOD = 998244353
_ROOT = 3


def _ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a, b, limit):
    out_len = min(limit, len(a) + len(b) - 1)
    if len(a) * len(b) <= 4096:
        out = [0] * out_len
        for i, x in enumerate(a):
            upto = min(len(b), out_len - i)
            for j in range(upto):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    n = 1
    full_len = len(a) + len(b) - 1
    while n < full_len:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:out_len]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1 through K with each letter count
    bounded by its corresponding entry in C, modulo 998244353.
    """
    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % _MOD
    invfact = [1] * (K + 1)
    invfact[K] = pow(fact[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % _MOD

    polys = []
    for cap in C:
        degree = min(cap, K)
        polys.append(invfact[:degree + 1])

    while len(polys) > 1:
        next_level = []
        for i in range(0, len(polys), 2):
            if i + 1 == len(polys):
                next_level.append(polys[i])
            else:
                next_level.append(_multiply(polys[i], polys[i + 1], K + 1))
        polys = next_level

    coeff = polys[0]
    return sum(coeff[n] * fact[n] for n in range(1, len(coeff))) % _MOD

from typing import List


MOD = 998244353


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of lengths 1 through K with per-letter occurrence caps."""
    inv_fact = [1] * (K + 1)
    for i in range(1, K + 1):
        inv_fact[i] = inv_fact[i - 1] * pow(i, MOD - 2, MOD) % MOD

    # Product of EGF polynomials for letters whose caps are below K.
    coeff = [0] * (K + 1)
    coeff[0] = 1
    unrestricted = 0
    for cap in C:
        if cap >= K:
            unrestricted += 1
            continue
        updated = [0] * (K + 1)
        for old_len, value in enumerate(coeff):
            if value == 0:
                continue
            for added in range(min(cap, K - old_len) + 1):
                updated[old_len + added] = (
                    updated[old_len + added] + value * inv_fact[added]
                ) % MOD
        coeff = updated

    fact = 1
    result = 0
    if unrestricted:
        # Unrestricted letters contribute exp(unrestricted*x).
        u_powers = [1] * (K + 1)
        for i in range(1, K + 1):
            u_powers[i] = u_powers[i - 1] * unrestricted % MOD
        for length in range(1, K + 1):
            fact = fact * length % MOD
            egf_coefficient = 0
            for old_len in range(length + 1):
                egf_coefficient += (
                    coeff[old_len]
                    * inv_fact[length - old_len]
                    % MOD
                    * u_powers[length - old_len]
                    % MOD
                )
            result = (result + fact * egf_coefficient) % MOD
    else:
        for length in range(1, K + 1):
            fact = fact * length % MOD
            result = (result + fact * coeff[length]) % MOD
    return result

